size(176, 200, 176, 2.5);
name("broad-crowned tree");

const W = 176, H = 200, D = 176, C = 88;
const BARK = "2:9";
const balls = [];

function clump(x, y, z, R) {
  x = Math.min(Math.max(x, R + 5), W - R - 5);
  z = Math.min(Math.max(z, R + 5), D - R - 5);
  y = Math.min(y, H - 0.8 * R - 5);
  const j = [];
  for (let i = 0; i < H / 2 + 2; i++) j.push(rng());
  balls.push({ x: x, y: y, z: z, R: R, jit: rng() * 1.5, band: j });
  return balls[balls.length - 1];
}

// wooden ribs from a branch end out to the leaf shell, so leaves hang on wood
function spokes(ex, ey, ez, b, a, dx, dy, dz) {
  const R = b.R - 1.5;
  for (let k = 0; k < 4; k++) {
    const sa = a + 0.785 + k * 1.5708;
    const up = 0.25;
    const cx = Math.cos(sa) * 0.968, cz = Math.sin(sa) * 0.968;
    tube("wood", BARK, ex, ey, ez, b.x + cx * R, b.y + up * 0.8 * R, b.z + cz * R, 2.6, 2.2);
  }
  tube("wood", BARK, ex, ey, ez, b.x, b.y + 0.8 * R, b.z, 2.6, 2.2);
  tube("wood", BARK, ex, ey, ez, b.x, b.y - 0.8 * R, b.z, 2.4, 2.2);
  tube("wood", BARK, ex, ey, ez, b.x + dx * R, b.y + dy * 0.8 * R, b.z + dz * R, 2.6, 2.2);
}

function grow(x, y, z, a, e, len, r, depth) {
  const dx = Math.cos(e) * Math.cos(a), dy = Math.sin(e), dz = Math.cos(e) * Math.sin(a);
  const ex = x + dx * len, ey = y + dy * len, ez = z + dz * len;
  const r1 = r * 0.8;
  tube("wood", BARK, x, y, z, ex, ey, ez, r, r1);
  if (depth === 0) {
    const R = 14 + rng() * 5;
    const b = clump(ex - dx * 0.4 * R, ey - dy * 0.4 * R, ez - dz * 0.4 * R, R);
    spokes(ex, ey, ez, b, a, dx, dy, dz);
    return;
  }
  const b = clump(ex, ey, ez, depth === 2 ? 19 + rng() * 4 : 16 + rng() * 5);
  spokes(ex, ey, ez, b, a, dx, dy, dz);
  const n = depth === 2 ? 3 : 2;
  for (let k = 0; k < n; k++) {
    let ca, ce;
    if (e > 1.2) {
      ca = a + k * 6.2832 / n + (rng() - 0.5) * 0.5;
      ce = 0.85 + rng() * 0.35;
    } else {
      ca = a + (k - (n - 1) / 2) * 0.85 + (rng() - 0.5) * 0.3;
      ce = Math.min(1.15, Math.max(0.3, e - 0.1 + (rng() - 0.5) * 0.6));
    }
    grow(ex, ey, ez, ca, ce, len * 0.72, r1, depth - 1);
  }
}

// trunk
tube("wood", BARK, C, 0, C, C + 1, 32, C - 1, 10.5, 9);
tube("wood", BARK, C + 1, 32, C - 1, C + 2, 64, C - 1, 9, 8);
// root flare
for (let i = 0; i < 6; i++) {
  const a = i * 1.047 + 0.3 + (rng() - 0.5) * 0.3;
  const l = 20 + rng() * 7;
  tube("wood", BARK, C + Math.cos(a) * 5, 18, C + Math.sin(a) * 5,
       C + Math.cos(a) * l, 1, C + Math.sin(a) * l, 5, 2.6);
}

// boughs
const a0 = rng() * 6.28;
for (let i = 0; i < 5; i++) {
  const a = a0 + i * 1.2566 + (rng() - 0.5) * 0.4;
  grow(C + 2, 54 + i * 2.5, C - 1, a, 0.7 + rng() * 0.3, 30 + rng() * 5, 6.5, 2);
}
grow(C + 2, 62, C - 1, rng() * 6.28, 1.47, 44, 7.5, 2);

// bark: fissures and ridges on the visible lower wood
for (let y = 0; y < 100; y++) {
  for (let x = 48; x < 130; x++) {
    for (let z = 48; z < 130; z++) {
      if (at(x, y, z) !== "wood") continue;
      if (at(x - 1, y, z) && at(x + 1, y, z) && at(x, y, z - 1) && at(x, y, z + 1)) continue;
      const ang = Math.atan2(z - (C - 1), x - (C + 1));
      const v = Math.sin(ang * 9 + Math.sin(y * 0.07) * 1.5 + y * 0.02);
      const u = Math.sin(ang * 23 + y * 0.11);
      let c = BARK;
      if (v < -0.55) c = "2:6";
      else if (v > 0.75) c = "3:8";
      else if (u > 0.8) c = "grey:10";
      put("wood", c, x, y, z);
    }
  }
}
// knot on the front of the trunk
ball("wood", BARK, C - 2, 40, C - 10.5, 3.4, 4.4, 2.8);
ball("wood", "2:6", C - 2, 40, C - 12.8, 1.7, 2.3, 1.2);

// leaves: one lumpy hollow shell around all clumps
const PAL = ["9:6", "8:6", "8:5", "7:5", "8:3", "7:3", "6:3", "6:2"];
for (let y = 45; y < H; y++) {
  const act = [];
  for (let i = 0; i < balls.length; i++) {
    const b = balls[i];
    if (Math.abs(y - b.y) < 0.8 * (b.R + 4)) act.push(b);
  }
  if (!act.length) continue;
  const g = (y - 70) / 120;
  for (let x = 0; x < W; x++) {
    const ax = [];
    for (let i = 0; i < act.length; i++) {
      if (Math.abs(x - act[i].x) < act[i].R + 4) ax.push(act[i]);
    }
    if (!ax.length) continue;
    for (let z = 0; z < D; z++) {
      let s = 1e9, best = null;
      for (let i = 0; i < ax.length; i++) {
        const b = ax[i];
        const ddx = x - b.x, ddy = (y - b.y) / 0.8, ddz = z - b.z;
        const d = Math.sqrt(ddx * ddx + ddy * ddy + ddz * ddz) - b.R;
        if (d < s) { s = d; best = b; }
      }
      if (s > 3) continue;
      s += 1.4 * Math.sin(x * 0.31 + y * 0.17) * Math.sin(z * 0.29 - y * 0.13) +
           0.5 * Math.sin((x + z) * 0.7 + y * 0.5);
      if (s > 0 || s <= -3) continue;
      if (at(x, y, z) !== null) continue;
      const t = (y - best.y) / (0.8 * best.R);
      let idx = Math.floor(1 + (t + 1) * 1.6 + g * 2 + best.jit + best.band[y >> 1] - 0.5);
      if (idx < 0) idx = 0;
      if (idx > 7) idx = 7;
      put("leaves", PAL[idx], x, y, z);
    }
  }
}
